import { storage } from "./storage.js";
const Task = class {
    constructor(title, desc, dueDate, priority, checked) {
        this.title = title;
        this.desc = desc;
        this.dueDate = dueDate;
        this.priority = priority;
        this.checked = checked;
    }
    toggleChecked() {
        this.checked = !this.checked;
    }
    getAllProperties() {
        return {
            title: this.title,
            desc: this.desc,
            dueDate: this.dueDate,
            priority: this.priority,
            checked: this.checked,
        }
    }
}

export const Project = class {
    constructor(projectName) {
        this.projectName = projectName;
    }
    #tasksArray = [];
    addTask(title, desc, dueDate, priority, checked) {
        const task = new Task(title, desc, dueDate, priority, checked);
        this.#tasksArray.push(task);
    }
    removeTask(taskTitle) {
        let i = 0;
        for (let task of this.#tasksArray) {
            if (task.title === taskTitle) {
                this.#tasksArray.splice(i, 1);
                return;
            }
            i += 1;
        }
    }
    removeAll() {
        this.#tasksArray = [];
    }
    getTasks() {
        return this.#tasksArray;
    }
}