// storage.js

import { projectManager } from "./projectManager.js";

const STORAGE_KEY = "odinTodoList";

export const storage = {
    saveData() {
        const projects = projectManager.getProjects();
        
        const cleanData = projects.map(project => {
            return {
                projectName: project.projectName,
                tasks: project.getTasks().map(task => task.getAllProperties()),
                
            };
        });

        localStorage.setItem(STORAGE_KEY, JSON.stringify(cleanData));
    },

    loadData() {
        const rawData = localStorage.getItem(STORAGE_KEY);
        if (!rawData) return false;

        const parsedProjects = JSON.parse(rawData);

        parsedProjects.forEach(rawProject => {
            const activeProjectInstance = projectManager.addProject(rawProject.projectName);

            rawProject.tasks.forEach(task => {
                activeProjectInstance.addTask(
                    task.title,
                    task.desc,
                    task.dueDate,
                    task.priority,
                    task.checked
                );
            });
        });

        return true;
    }
};