// cleaner code

import { projectManager } from "./projectManager.js";
import { storage } from "./storage.js";

const projectListContainer = document.getElementById("project-list");
const currentProjectTitle = document.getElementById("current-project-title");
const taskListContainer = document.getElementById("task-list");

const projectModal = document.getElementById("project-modal");
const taskModal = document.getElementById("task-modal");

const projectForm = document.getElementById("project-form");
const taskForm = document.getElementById("task-form");

const newProjectNameInput = document.getElementById("new-project-name");
const newTaskTitleInput = document.getElementById("new-task-title");
const newTaskDescInput = document.getElementById("new-task-desc");
const newTaskDateInput = document.getElementById("new-task-date");
const newTaskPriorityInput = document.getElementById("new-task-priority");

const addProjectBtn = document.getElementById("add-project-btn");
const addTaskBtn = document.getElementById("add-task-btn");
const closeProjectModalBtn = document.getElementById("close-project-modal");
const closeTaskModalBtn = document.getElementById("close-task-modal");


const createElement = (tag, className, textContent = "") => {
    const element = document.createElement(tag);
    if (className) element.classList.add(className);
    if (textContent) element.textContent = textContent;
    return element;
};

const renderProjects = function () {
    projectListContainer.innerHTML = "";

    const projects = projectManager.getProjects();
    if (!projects) return;

    projects.forEach(project => {
        const projectName = project.projectName;

        const projectCard = createElement("li", "project-card");
        const nameElement = createElement("h2", "project-name", projectName);
        const removeBtn = createElement("button", "remove-project", "Remove");

        removeBtn.addEventListener("click", (event) => {
            event.stopPropagation();
            projectManager.setNullActiveProject();
            projectManager.removeProject(projectName);
            storage.saveData();
            renderProjects();
            renderTasks();
        });
        projectCard.addEventListener("click", () => {
            projectManager.setActiveProject(projectName);
            renderTasks();
        });

        projectCard.append(nameElement, removeBtn);

        projectListContainer.appendChild(projectCard);
    });
}

const renderTasks = function () {
    taskListContainer.innerHTML = "";

    const activeProject = projectManager.getActiveProject();
    if (activeProject === null) {
        currentProjectTitle.textContent = "No Active Project";
        taskListContainer.textContent = "";
        return;
    }

    currentProjectTitle.textContent = activeProject.projectName;
    const tasksArray = activeProject.getTasks();

    tasksArray.forEach(task => {
        const taskCard = createElement("div", "task-card");

        const taskTitle = createElement("div", "title", task.title);
        const taskDesc = createElement("div", "description", task.desc);
        const dueDate = createElement("div", "due-date", task.dueDate);
        const priority = createElement("div", "priority", task.priority);
        
        const checkedCheckbox = createElement("input", "checked-box");
        checkedCheckbox.type = "checkbox";
        checkedCheckbox.checked = task.checked; // Sets the box to checked if true

        checkedCheckbox.addEventListener("change", () => {
            task.toggleChecked();
            storage.saveData();
        });

        const removeTaskBtn = createElement("button", "remove-task", "Remove");

        removeTaskBtn.addEventListener("click", (event) => {
            event.stopPropagation();
            activeProject.removeTask(task.title);
            storage.saveData();
            renderTasks();
        });

        taskCard.append(taskTitle, taskDesc, dueDate, priority, checkedCheckbox, removeTaskBtn);

        taskListContainer.appendChild(taskCard);

    });

}

const bindListeners = function () {

    addProjectBtn.addEventListener("click", (event) => {
        projectModal.showModal();
    });

    closeProjectModalBtn.addEventListener("click", (event) => {
        projectForm.reset();
        projectModal.close();
    });

    addTaskBtn.addEventListener("click", (event) => {
        const activeProject = projectManager.getActiveProject();
        if (activeProject === null) {
            return;
        }
        taskModal.showModal();
    });
    closeTaskModalBtn.addEventListener("click", (event) => {
        taskForm.reset();
        taskModal.close();
    });
    projectForm.addEventListener("submit", (event) => {
        event.preventDefault();
        const newProjectName = newProjectNameInput.value;
        projectManager.addProject(newProjectName);
        storage.saveData();
        projectForm.reset();
        projectModal.close();
        renderProjects();
        renderTasks();
    });

    taskForm.addEventListener("submit", (event) => {
        event.preventDefault();
        const newTaskTitle = newTaskTitleInput.value;
        const newTaskDesc = newTaskDescInput.value;
        const newTaskDate = newTaskDateInput.value;
        const newTaskPriority = newTaskPriorityInput.value;

        const activeProject = projectManager.getActiveProject();
        if (activeProject === null) {
            taskForm.reset();
            taskModal.close();
            return;
        }
        activeProject.addTask(newTaskTitle, newTaskDesc, newTaskDate, newTaskPriority, false);
        storage.saveData();

        taskForm.reset();
        taskModal.close();
        renderTasks();
    });
}

export const DisplayController = {
    init() {
        renderProjects();
        renderTasks();
        bindListeners();
    }
}
