// index.js

import "./styles.css";
import { projectManager } from "./projectManager.js";
import { storage } from "./storage.js";
import { DisplayController } from "./displayController.js";

const dataLoadedSuccessfully = storage.loadData();

if (dataLoadedSuccessfully) {
    const allProjects = projectManager.getProjects();
    if (allProjects.length > 0) {
        projectManager.setActiveProject(allProjects[0].projectName);
    }
} else {
    const def = projectManager.addProject("Default");
    projectManager.setActiveProject(def.projectName);
    storage.saveData();
}

DisplayController.init();

