// projectManager.js
// newer and cleaner code
import { Project } from "./Todo.js"

const ProjectManager = class {
    #projects = [];
    #activeProject = null;

    addProject(projectName) {
        const newProject = new Project(projectName);
        this.#projects.push(newProject);
        return newProject;

    }
    removeProject(projectName) {
        const index = this.#projects.findIndex(project => project.projectName === projectName);
        if (index !== -1) {
            this.#projects[index].removeAll();
            this.#projects.splice(index, 1);
            return;
        }
    }
    getProjects() {
        return this.#projects;
    }
    getActiveProject() {
        return this.#activeProject;
    }
    setActiveProject(projectName) {
        const index = this.#projects.findIndex(project => project.projectName === projectName);
        if (index !== -1) {
            this.#activeProject = this.#projects[index];
            return this.#activeProject;
        }
    }
    setNullActiveProject() {
        this.#activeProject = null;
    }
}

export const projectManager = new ProjectManager();

